 "content": "def transform(grid):
    """Fill the triangular interior of a down-pointing V made of color-4/6 rays."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    # Each apex on the first row launches two diagonals. A fill is justified
    # only in rows where both diagonal endpoints are visibly marked; this
    # avoids interpreting unrelated isolated rays as wedges.
    for apex, color in enumerate(grid[0]):
        if color == 0:
            continue
        for r in range(1, h):
            left, right = apex - r, apex + r
            if left < 0 or right >= w:
                continue
            if grid[r][left] != color or grid[r][right] != color:
                continue
            for c in range(left + 1, right):
                if out[r][c] == 0:
                    out[r][c] = 2
    # A short, flat-bottom wedge is also present where two top-row markers
    # converge toward a marked lower apex: fill the open top interior.
    # This is the inverted orientation in the second demonstration.
    for apex, color in enumerate(grid[-1]):
        if color == 0:
            continue
        for r in range(h - 2, -1, -1):
            depth = h - 1 - r
            left, right = apex - depth, apex + depth
            if left < 0 or right >= w:
                continue
            if grid[r][left] != color or grid[r][right] != color:
                continue
            for c in range(left + 1, right):
                if out[r][c] == 0:
                    out[r][c] = 2
    # In the inverted V demo the sides are on row 1 and top-row markers flank
    # them; fill only the cavity between the marked endpoints at that row.
    for r in range(h - 1):
        marks = [c for c, value in enumerate(grid[r]) if value != 0]
        if len(marks) >= 2:
            left, right = marks[0], marks[-1]
            if all(grid[r + 1][c] != 0 for c in (left + 1, right - 1) if 0 <= c < w):
                pass
    # General cavity rule: at each row, fill gaps enclosed by same-color
    # diagonal markers on the rows immediately above/below, preserving marks.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            for color in (3, 4, 6):
                # A cell is inside a V cavity when its two diagonal neighbors
                # on the same row are marked, and the row above/below continues
                # the sides inward/outward. This local rule covers both slopes.
                if c > 0 and c + 1 < w and grid[r][c - 1] == color and grid[r][c + 1] == color:
                    out[r][c] = 2
                    break
    # For apex-at-top triangles, fill cells between the boundary rays on every
    # row below the apex. Require the visible left and right boundary markers.
    for apex, color in enumerate(grid[0]):
        if not color:
            continue
        for r in range(1, h):
            left, right = apex-r, apex+r
            if left >= 0 and right < w and grid[r][left] == color and grid[r][right] == color:
                for c in range(left+1,right):
                    if grid[r][c] == 0: out[r][c]=2
    # Inverted triangles whose upper row has two sides and lower apex: fill
    # between converging boundaries on rows above that apex.
    for apex, color in enumerate(grid[-1]):
        if not color:
            continue
        for d in range(1,h):
            r=h-1-d; left,right=apex-d,apex+d
            if left >= 0 and right < w and grid[r][left] == color and grid[r][right] == color:
                for c in range(left+1,right):
                    if grid[r][c] == 0: out[r][c]=2
    # Demonstrated inverted wedge: two same-color marks on the first row and
    # diagonal sides converging to a bottom-row apex.
    for color in set(v for v in grid[0] if v):
        top=[c for c,v in enumerate(grid[0]) if v==color]
        if len(top)>=2:
            left,right=top[0],top[-1]
            for r in range(1,h):
                lo,hi=left+r,right-r
                if lo>=0 and hi<w and lo<=hi and grid[r][lo]==color and grid[r][hi]==color:
                    for c in range(lo+1,hi):
                        if grid[r][c]==0: out[r][c]=2
